#include <stdio.h>

int main() {
    int n, contador, puntuacion;
    float suma, promedio;

    printf("Cuantas encuestas vas a procesar? ");
    scanf("%d", &n);

    suma = 0;
    contador = 0;

    while (contador < n) {
        printf("Puntuacion (1-5): ");
        scanf("%d", &puntuacion);
        suma = suma + puntuacion;
        contador = contador + 1;
    }

    promedio = suma / n;
    printf("Promedio de satisfaccion: %.2f\n", promedio);

    return 0;
}
